def coverage(a):return all(complete(a.get('lexicon',{}).get(w)) for w in wordset(a['pairs']))
def canonical(link):
    u=urllib.parse.urlsplit(link);return (u.hostname or '').removeprefix('www.')+u.path.rstrip('/')
